   want=$(choose)
   if [ "$want" != "$cur" ]; then
     bad=$((bad+1))
     if [ "$bad" -ge "$FAILS_NEED" ] || [ -z "$cur" ]; then
       apply_west "$want"
       cur="$want"
       bad=0
     fi
   else
