 # running interface MTU, so an existing interface is aligned in place below.
 wg_conf_mtu() {
   case "$1" in
     m00) echo 1420 ;;
     m01) echo 1420 ;;
     m12) echo 1420 ;;
     m13) echo 1420 ;;
-    m14) echo 1420 ;;
-    m15) echo 1420 ;;
-    m16) echo 1420 ;;
+    m14) echo 1380 ;;
+    m15) echo 1380 ;;
+    m16) echo 1380 ;;
     m17) echo 1420 ;;
-    m18) echo 1420 ;;
+    m18) echo 1380 ;;
     m20) echo 1280 ;;
     *) echo "" ;;
   esac
 }
 for iface in m00 m01 m12 m13 m14 m15 m16 m17 m18 m20; do
   conf="/etc/wireguard/$iface.conf"
   if [ ! -f "$conf" ]; then
     echo "meridian-wg-missing: $conf is listed in this manifest but not installed" >&2
     exit 1
   fi
